      case 12:
        return 20;
      case 13:
        return 22;
      case 14:
        return 22;
      case 16:
        return 24;
      case 20:
        return 28;
      case 24:
        return 32;
      case 36:
        return 44;
      case 48:
        return 56;
      case 56:
        return 64;
      default:
        return null;
    }
  }

  /// Weights actually used by the design file, keyed by "sizeN.wWWW".
  static const Map<String, FontWeight> weights = <String, FontWeight>{
  'size10.w400': FontWeight.w400,
  'size10.w600': FontWeight.w600,
  'size12.w400': FontWeight.w400,
  'size12.w500': FontWeight.w500,
  'size12.w600': FontWeight.w600,
  'size13.w400': FontWeight.w400,
  'size13.w500': FontWeight.w500,
  'size13.w600': FontWeight.w600,
  'size14.w400': FontWeight.w400,
  'size14.w500': FontWeight.w500,
  'size14.w600': FontWeight.w600,
  'size14.w700': FontWeight.w700,
  'size16.w400': FontWeight.w400,
  'size16.w500': FontWeight.w500,
  'size16.w600': FontWeight.w600,
  'size20.w400': FontWeight.w400,
  'size20.w500': FontWeight.w500,
  'size20.w600': FontWeight.w600,
  'size24.w400': FontWeight.w400,
  'size24.w500': FontWeight.w500,
  'size24.w600': FontWeight.w600,
  'size36.w400': FontWeight.w400,
  'size36.w500': FontWeight.w500,
  'size36.w600': FontWeight.w600,
  'size48.w400': FontWeight.w400,
  'size48.w500': FontWeight.w500,
  'size48.w600': FontWeight.w600,
  'size56.w400': FontWeight.w400,
  'size56.w500': FontWeight.w500,
  'size56.w600': FontWeight.w600,
  };
}

/// Spacing scale.
///
/// Approved scale: 4 / 8 / 12 / 16 / 20 px, every step divisible by two.
/// The rationale lives in design/variables/scales.json.
abstract final class ArcoSpace {
  static const double spaceXs = 4;
  static const double spaceSm = 8;
  static const double spaceMd = 12;
  static const double spaceLg = 16;
  static const double spaceXl = 20;
}

/// Corner radius scale.
abstract final class ArcoRadius {
  static const double radiusSm = 2;
  static const double radiusMd = 4;
  static const double radiusLg = 8;
  static const double radiusFull = 999;
}

/// Control heights.
///
/// Measured from the geometry of the Arco kit: 30 variants per size, zero variance. Every control carries its own horizontal padding because the button needs both values together, and both land on the approved spacing scale. The measurement comes from the Arco kit geometry rather than from the Figma file, whose account is rate limited; the values match the ones the tokens already carried.
abstract final class ArcoControl {
  static const double heightMini = 24;
  static const double paddingMini = 12;
  static const double heightSmall = 28;
  static const double paddingSmall = 16;
  static const double heightMedium = 32;
  static const double paddingMedium = 16;
  static const double heightLarge = 36;
  static const double paddingLarge = 20;
}

/// Tag heights.
///
/// Measured from the Tag geometry: 91 variants per size, zero variance. The tag is four pixels shorter than the control of the equivalent name, so it gets its own scale rather than reusing the control one.
abstract final class ArcoTag {
  static const double heightMini = 20;
  static const double heightSmall = 24;
  static const double heightMedium = 28;
  static const double heightLarge = 32;
}
